declare module 'tree-sitter' {
    class Parser {
        setLanguage(language: any): void;
        parse(input: string, oldTree?: any, options?: any): any;
    }
    namespace Parser {
        interface SyntaxNode {
            type: string;
            text: string;
            startIndex: number;
            endIndex: number;
            startPosition: { row: number; column: number };
            endPosition: { row: number; column: number };
            parent: SyntaxNode | null;
            children: SyntaxNode[];
            nameNode?: SyntaxNode;
            argumentsNode?: SyntaxNode;
            [key: string]: any;
        }
        interface Tree {
            rootNode: SyntaxNode;
        }
    }
    export = Parser;
}

declare module 'tree-sitter-java' {
    const language: any;
    export = language;
}
